// ---- Step 0: Get API key for SOC user ----
// Look up SOC user by login query (avoids @ in URL path), then renew key by internal ID
const adminCreds = Buffer.from('admin@thehive.local:secret').toString('base64');
const adminHeaders = {
  'Authorization': `Basic ${adminCreds}`,
  'Content-Type': 'application/json',
};

// Find the SOC user's internal ID
const usersResp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://thehive:9000/api/v1/query',
  headers: adminHeaders,
  body: {
    query: [
      { _name: 'listUser' },
      { _name: 'filter', _eq: { _field: 'login', _value: 'analyst@bsides-lab.local' } },
    ]
  },
  json: true,
});

if (!Array.isArray(usersResp) || usersResp.length === 0) {
  throw new Error('SOC user analyst@bsides-lab.local not found. Run load_sample_data.py first.');
}
const socUserId = usersResp[0]._id;

// Renew API key using internal ID (no @ in URL)
const keyResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `http://thehive:9000/api/v1/user/${socUserId}/key/renew`,
  headers: adminHeaders,
});
const apiKey = String(keyResp).trim().replace(/^\"|\"/g, '');

const thehiveHeaders = {
  'Authorization': `Bearer ${apiKey}`,
  'Content-Type': 'application/json',
};

// ---- Step 1: Fetch latest unread alert from TheHive ----
const alertsResp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://thehive:9000/api/v1/query',
  headers: thehiveHeaders,
  body: {
    query: [
      { _name: 'listAlert' },
      { _name: 'filter', _eq: { _field: 'status', _value: 'New' } },
      { _name: 'sort', _fields: [{ lastSyncDate: 'desc' }] },
      { _name: 'page', from: 0, to: 1 }
    ]
  },
  json: true,
});

let alert;
if (Array.isArray(alertsResp) && alertsResp.length > 0) {
  alert = alertsResp[0];
} else {
  throw new Error('No new alerts found in TheHive. Run load_sample_data.py first.');
}

const alertTags = alert.tags || [];
const thehiveAlertId = alert._id;

// ---- Step 2: Load ALL playbooks (agent picks the right one) ----
const fs = require('fs');
const path = require('path');
const playbookDir = '/home/node/playbooks';
const playbooks = [];

const files = fs.readdirSync(playbookDir).filter(f => f.endsWith('.md') && f !== 'index.md');
for (const file of files) {
  const content = fs.readFileSync(path.join(playbookDir, file), 'utf8');
  playbooks.push({ file, content });
}

if (playbooks.length === 0) {
  throw new Error('No playbooks found in /home/node/playbooks');
}

// Build a combined string: each playbook labeled by filename
const allPlaybooks = playbooks.map(p => `### ${p.file}\n${p.content}`).join('\n\n---\n\n');

// ---- Step 3: Get field mappings for the system prompt ----
const mappings = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://mcp-server:3001/api/mappings/auth_logs',
  json: true,
});

// ---- Step 4: Initialize per-triage budget ----
const budgetResp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://mcp-server:3001/api/budget/start',
  headers: { 'Content-Type': 'application/json' },
  body: { session_id: thehiveAlertId },
  json: true,
});

return [{
  json: {
    thehive_alert_id: thehiveAlertId,
    thehive_api_key: apiKey,
    alert_title: alert.title,
    alert_description: alert.description,
    alert_severity: alert.severity,
    alert_tags: alertTags,
    alert_source: alert.source,
    alert_date: alert.date,
    playbook_files: playbooks.map(p => p.file),
    all_playbooks: allPlaybooks,
    field_mappings: mappings.fields,
    budget: budgetResp,
  }
}];

