// Write triage verdict back to the TheHive alert
const triageOutput = $input.first().json.output || $input.first().json.text || 'No triage output';
const thehiveAlertId = $('Fetch TheHive Alert & Match Playbook').first().json.thehive_alert_id;
const apiKey = $('Fetch TheHive Alert & Match Playbook').first().json.thehive_api_key;
const playbookFiles = $('Fetch TheHive Alert & Match Playbook').first().json.playbook_files.join(', ');

const headers = {
  'Authorization': `Bearer ${apiKey}`,
  'Content-Type': 'application/json',
};

// Fetch final budget status from MCP server
let costSummary = '';
try {
  const budgetResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://mcp-server:3001/api/budget',
    json: true,
  });
  costSummary = `\n\n### Cost Summary\n- Queries used: ${budgetResp.queries_used} / ${budgetResp.max_queries}\n- Estimated cost: $${budgetResp.estimated_cost_usd} / $${budgetResp.budget_usd} budget\n- Budget remaining: $${budgetResp.budget_remaining_usd}`;
} catch (e) {
  costSummary = '\n\n_Cost tracking unavailable_';
}

// Update the alert description with the triage verdict
const originalDesc = $('Fetch TheHive Alert & Match Playbook').first().json.alert_description;
const updatedDesc = originalDesc + '\n\n---\n\n## Agent Triage Report\n\n' + triageOutput + costSummary + '\n\n---\n_Available playbooks: ' + playbookFiles + ' | Triaged by Agentic SOC Pipeline_';

const updateResp = await this.helpers.httpRequest({
  method: 'PATCH',
  url: `http://thehive:9000/api/v1/alert/${thehiveAlertId}`,
  headers,
  body: {
    description: updatedDesc,
    summary: 'Triaged by Agentic SOC — see description for full analysis',
  },
  json: true,
});

return [{
  json: {
    status: 'success',
    thehive_alert_id: thehiveAlertId,
    message: 'Triage verdict written back to TheHive alert',
    thehive_url: `http://localhost:9000`,
  }
}];
